import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------------------------------------------------------------------------
# CUDA kernel and C++ wrapper (compiled at import time)
# ---------------------------------------------------------------------------
src_cuda = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void mse_kernel(const half* __restrict__ pred,
                           const half* __restrict__ tgt,
                           float* __restrict__ out_sum,
                           size_t N) {
    extern __shared__ float sdata[];
    const unsigned int tid = threadIdx.x;
    const unsigned int idx = blockIdx.x * blockDim.x + tid;
    float sum = 0.0f;

    // grid‑stride loop
    for (size_t i = idx; i < N; i += blockDim.x * gridDim.x) {
        const half p = pred[i];
        const half t = tgt[i];
        const float diff = __half2float(p) - __half2float(t);
        sum += diff * diff;
    }

    sdata[tid] = sum;
    __syncthreads();

    // intra‑block reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // thread 0 adds block result to global accumulator
    if (tid == 0) {
        atomicAdd(out_sum, sdata[0]);
    }
}
'''

src_cpp = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda.h>
#include <cuda_runtime.h>

// forward declaration of the kernel
void mse_kernel(const half* pred,
                const half* tgt,
                float* out_sum,
                size_t N,
                dim3 grid,
                dim3 block,
                size_t shared_mem,
                cudaStream_t stream);

torch::Tensor mse_forward(torch::Tensor pred, torch::Tensor tgt) {
    TORCH_CHECK(pred.is_cuda() && tgt.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(pred.dtype() == torch::kHalf && tgt.dtype() == torch::kHalf,
                "inputs must be float16");
    TORCH_CHECK(pred.sizes() == tgt.sizes(), "input shapes must match");

    const int64_t N = pred.numel();
    auto out_sum = torch::zeros({1},
                                torch::dtype(torch::kFloat32).device(pred.device()));

    const int threads = 256;
    const int blocks = std::min<int64_t>(65535, (N + threads - 1) / threads);
    const size_t shared_mem = threads * sizeof(float);
    const cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    mse_kernel<<<dim3(blocks), dim3(threads), shared_mem, stream>>>(
        reinterpret_cast<const half*>(pred.data_ptr()),
        reinterpret_cast<const half*>(tgt.data_ptr()),
        out_sum.data_ptr<float>(),
        static_cast<size_t>(N));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }

    // synchronize to make sure the result is ready
    cudaStreamSynchronize(stream);

    float sum = out_sum.item<float>();
    float mean = sum / static_cast<float>(N);
    // return as float16 scalar tensor
    return torch::tensor(static_cast<at::Half>(mean),
                         torch::dtype(torch::kHalf).device(pred.device()));
}

// binding
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mse_forward", &mse_forward, "MSE forward (CUDA)");
}
'''

# compile the extension
_mse_ext = load_inline(name='mse_ext',
                       cpp_sources=src_cpp,
                       cuda_sources=src_cuda,
                       functions=['mse_forward'],
                       verbose=False)

# ---------------------------------------------------------------------------
# Model that uses the custom CUDA kernel
# ---------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Computes mean squared error using a fused CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        return _mse_ext.mse_forward(predictions, targets)

# ---------------------------------------------------------------------------
# Helper to generate test inputs (mirrors reference)
# ---------------------------------------------------------------------------
def get_inputs():
    scale = torch.rand(()).to(torch.float16).cuda()
    preds = (torch.rand(32768, 32768, dtype=torch.float16, device='cuda') * scale)
    tgts = torch.rand(32768, 32768, dtype=torch.float16, device='cuda')
    return [preds, tgts]

def get_init_inputs():
    return []

if __name__ == "__main__":
    # quick sanity check
    model = ModelNew().cuda()
    preds, tgts = get_inputs()
    loss = model(preds, tgts)
    print("MSE loss:", loss.item())
